/** A single HTOC-published hymn (troparion or kontakion) for one day. */
export interface HtocHymn {
	/** Display title, e.g. `"Troparion, Tone IV"` or `"Holy Martyr Boniface"`. */
	readonly title: string;
	/** Hymn text. `"No Troparion is given for this service in the Menaion."` is
	 *  used as a placeholder on days with no troparion for the ranked saint. */
	readonly text: string;
	/** Order-group as scraped from HTOC (used to recover display order on days
	 *  with multiple saints). */
	readonly group: number;
	/** Saints this hymn is attached to. `slug` matches `HtocSaint.slug` so a
	 *  consumer can join propers to the day's commemoration list without any
	 *  cId lookup. May be empty for day-level (resurrectional / feast) propers. */
	readonly saints: readonly { readonly name: string; readonly slug: string }[];
}

/** A single commemoration as printed on HTOC's day page: the authoritative
 *  user-facing list of saints / feasts / commemorations for the day, with
 *  HTOC's rank glyph and (optionally) life-page links. Superset of the
 *  navigable `HtocSaint` list — includes New Hieromartyrs and other entries
 *  that have no life page and therefore no `cId` to join to Ponomar XML. */
export interface HtocCommemoration {
	/** HTOC rank glyph: `6` Great Feast / `4` Vigil-Polyeleos / `3` Doxology /
	 *  `2` Six-stich / `1` Simple / `0` No sign / `o` Octoechos (weekday). */
	readonly rank: string;
	/** Display text as printed on the day page, with punctuation. */
	readonly text: string;
	/** `true` for minor commemorations grouped as a sub-bullet under a main entry. */
	readonly minor: boolean;
	/** Life-page links. `slug` matches `HtocSaint.slug` when the commemoration
	 *  has a life page in `htocSaints.ts`; empty for entries without a life. */
	readonly lives: readonly { readonly name: string; readonly slug: string }[];
}

/** HTOC day-level facts: title line, tone, fast rule, commemoration list,
 *  and the day's propers. */
export interface HtocDayFacts {
	/** Header line as scraped, e.g. `"28th Week after Pentecost. Tone two."`. */
	readonly headerText: string;
	/** Resurrectional tone of the week (1..8), or `null` on Bright Week and
	 *  Great Feasts of the Lord where HTOC does not print a tone. */
	readonly tone: number | null;
	/** Fast-rule display string, e.g. `"Nativity (St. Philip's Fast). By
	 *  Monastic Charter: Strict Fast (Bread, Vegetables, Fruits)"`. Empty
	 *  string on non-fast days. */
	readonly fastText: string;
	/** Full commemoration list as published by HTOC, in display order. */
	readonly commemorations: readonly HtocCommemoration[];
	/** Day's troparia in HTOC publication order. */
	readonly troparia: readonly HtocHymn[];
	/** Day's kontakia in HTOC publication order. */
	readonly kontakia: readonly HtocHymn[];
}

